'use strict';

const got = require('../got-wrapper');

module.exports = class YandexLoggerSentryTransport {
    /**
     * @param {got.OptionsInit} [options]
     */
    constructor(options) {
        this.options = options || {};
    }

    /**
     * @param {Raven.Client} client
     * @param {String} body
     * @param {Object} headers
     * @param {String} eventId
     * @param {Function} [cb]
     * @returns {Promise}
     */
    send(client, body, headers, eventId, cb) {
        let url = `${client.dsn.protocol}://${client.dsn.host}:${client.dsn.port || 80}${client.dsn.path}api/${client.dsn.project_id}/store/`;

        let options = Object.assign({
            method: 'POST',
            headers,
            body,
            ca: client.ca,
            timeout: client.sendTimeout * 1000,
        }, this.options);

        return got(url, options)
            .then(() => {
                client.emit('logged', eventId);

                if (cb) {
                    cb(null, eventId);
                }
            })
            .catch(err => {
                let response = err.response || {};
                let reason = response.headers && response.headers['x-sentry-error'];
                let statusCode = response.statusCode;
                let e = new Error(`HTTP Error (${statusCode}): ${reason}`);

                Object.assign(e, {
                    eventId,
                    reason,
                    response,
                    statusCode: response.statusCode,
                    sendMessage: body,
                    requestHeaders: headers,
                });

                client.emit('error', e);

                if (cb) {
                    cb(e);
                }
            });
    }
};
